#include <map>
#include <print>
#include <string>

int main() {
    std::map<std::string, int> scores;
    scores["小明"] = 88;                     // 写入：键 → 值
    scores["小强"] = 72;
    scores["小红"] = 95;
    for (const auto& [name, score] : scores) {
        std::println("{:<6} {}", name, score);
    }
    scores["小明"] = 90;                      // 键已经有了：改值，不新增
    std::println("一共 {} 条记录", scores.size());
    std::println("小红 = {}", scores["小红"]);      // 同一个写法，这次是查询
    return 0;
}

